package com.example.demo.model;
import org.springframework.stereotype.Component;
@Component public class Employee { private Long id=250101L; private String name="Aditya Software Engineer"; private String department="AI & ML Development"; public Long getId(){return id;} public String getName(){return name;} public String getDepartment(){return department;} public String toString(){return "Employee [ID="+id+", Name="+name+", Dept="+department+"]";} }